<script setup>
/**
 * @author Darwin Montes
 * @version 1.0.0
 * @created_at 2026-06-26
 * @module {Features.Home}
 * @resource {Home}
 */

import { ref, reactive, onMounted, onUnmounted, computed } from 'vue';
import { useAuthStore } from '@store/modules/auth.js';
import loboHeroImg from '@/assets/images/lobo-express-hero.png';
import { toast } from '@/utils/toast.js';

const authStore = useAuthStore();

// Estado de la autenticación en el navbar
const isAuthenticated = computed(() => !!(authStore.isAuthenticated && authStore.accessToken));

// Menú móvil
const mobileMenuOpen = ref(false);

// Tabs (Nosotros)
const activeTab = ref('about-us');

// FAQ Accordion
const activeFaqIndex = ref(null);
const toggleFaq = (index) => {
  if (activeFaqIndex.value === index) {
    activeFaqIndex.value = null;
  } else {
    activeFaqIndex.value = index;
  }
};

// Hero Carousel
const currentHeroIndex = ref(0);
const heroSlides = [
  { img: loboHeroImg },
  { img: 'https://images.unsplash.com/photo-1544620347-c4fd4a3d5957?w=1600&q=85' },
  { img: 'https://images.unsplash.com/photo-1570125909232-eb263c188f7e?w=1600&q=85' },
  { img: 'https://images.unsplash.com/photo-1449965408869-eaa3f722e40d?w=1600&q=85' },
  { img: 'https://images.unsplash.com/photo-1519749810606-6e80b8e71f93?w=1600&q=85' },
  { img: 'https://images.unsplash.com/photo-1494976388531-d1058494cdd8?w=1600&q=85' }
];


let carouselInterval = null;

const startCarousel = () => {
  stopCarousel();
  carouselInterval = setInterval(() => {
    nextHeroSlide();
  }, 5000);
};

const stopCarousel = () => {
  if (carouselInterval) {
    clearInterval(carouselInterval);
    carouselInterval = null;
  }
};

const nextHeroSlide = () => {
  currentHeroIndex.value = (currentHeroIndex.value + 1) % heroSlides.length;
};

const prevHeroSlide = () => {
  currentHeroIndex.value = (currentHeroIndex.value - 1 + heroSlides.length) % heroSlides.length;
};

const goToHeroSlide = (index) => {
  currentHeroIndex.value = index;
};

onMounted(() => {
  startCarousel();
});

onUnmounted(() => {
  stopCarousel();
});

// Formulario de Contacto
const contactForm = reactive({
  nombre: '',
  empresa: '',
  telefono: '',
  email: '',
  servicio: '',
  mensaje: ''
});
const isSubmittingContact = ref(false);

const handleContactSubmit = () => {
  isSubmittingContact.value = true;
  setTimeout(() => {
    isSubmittingContact.value = false;
    
    toast('¡Mensaje Enviado!', 'Nos pondremos en contacto contigo lo antes posible.', 'success');
    // Reset form
    contactForm.nombre = '';
    contactForm.empresa = '';
    contactForm.telefono = '';
    contactForm.email = '';
    contactForm.servicio = '';
    contactForm.mensaje = '';
  }, 1000);
};

// Scroll Reveal
const visibleElements = ref(new Set());
let intersectionObserver = null;

onMounted(() => {
  intersectionObserver = new IntersectionObserver((entries) => {
    entries.forEach((entry) => {
      if (entry.isIntersecting) {
        visibleElements.value.add(entry.target.id || entry.target.className);
        entry.target.classList.add('visible');
      }
    });
  }, { threshold: 0.12 });

  document.querySelectorAll('.reveal').forEach((el) => {
    intersectionObserver.observe(el);
  });
});

onUnmounted(() => {
  if (intersectionObserver) {
    intersectionObserver.disconnect();
  }
});

// Link activo en scroll
const activeSection = ref('');
const handleScroll = () => {
  const sectionsList = document.querySelectorAll('section[id]');
  let currentSec = '';
  sectionsList.forEach((s) => {
    if (window.scrollY >= s.offsetTop - 120) {
      currentSec = s.id;
    }
  });
  activeSection.value = currentSec;
};

onMounted(() => {
  window.addEventListener('scroll', handleScroll);
});

onUnmounted(() => {
  window.removeEventListener('scroll', handleScroll);
});

// Hacer que el contenedor #app ocupe todo el ancho mientras esta vista esté activa
onMounted(() => {
  const app = document.getElementById('app');
  if (app) app.classList.add('home-active');
  
  const container = document.querySelector('[data-layout="container"]');
  if (container) {
    container.classList.remove('container');
    container.classList.add('container-fluid');
    container.classList.add('home-layout-active');
  }
});
onUnmounted(() => {
  const app = document.getElementById('app');
  if (app) app.classList.remove('home-active');
  
  const container = document.querySelector('[data-layout="container"]');
  if (container) {
    container.classList.remove('container-fluid');
    container.classList.remove('home-layout-active');
    container.classList.add('container');
  }
});
</script>

